from pathlib import Path
import json
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0561-B{k:04d}']=t
p(153,'999.M41——九头蛇之子与盟军，对大漩涡周边的极限战士子战团发动猛烈袭击。')
p(165,'???.M42 - The Nachmund Rift War 纳克蒙德裂隙战争')
p(174,'真正攻击帝国目标之前，阿尔法军团会进行周密准备，以间谍活动与腐化削弱敌人的意志。他们从各个方向发动袭击，并协调每一击，力求造成最大破坏。许多行动都旨在利用、支援当地邪教徒：教派大力散布宣传、实施破坏、煽动骚乱与叛乱，在军团出击前分散敌方注意、消耗其力量。阿尔法军团也会与其他反帝国势力结盟，包括叛徒军团和异形。远离恐惧之眼时，他们较少倚仗恶魔，因为恶魔难以长时间稳定存在，发挥的作用有限；但若成功控制当地混沌教派，军团便可借其召唤恶魔，增添战术手段。')
p(176,'Alpha Legion member dressed in the colours of the White Scars during the Horus Heresy 荷鲁斯之乱期间，伪装为白疤涂装的阿尔法军团战士')
p(178,'阿尔法军团的战法与其他混沌星际战士军团、战帮截然不同。他们偏好避开正面交战，以诡计、渗透、破坏、洗脑和筹划多年的周密计划摧毁敌人。连战士的身份本身都是谜：他们使用的往往是秘密小组成员共用的化名，因此一个人的姓名与身份，可能实际对应多人。军团还用基因易容技术改变外貌，让帝国当局难辨真身。共用化名的习惯，也使成员常将自己看作更大集体身份的一部分。即使公开现身，他们也多让邪教徒与下属承担主要战斗，自己等待决胜一击或脱身的时机。')
p(180,'阿尔法军团最臭名昭著的战术，或许便是“折磨”：将隐秘谋划与压倒性武力结合，既讲究精密计划，也沉迷于别出心裁的残酷。行动先由特工或邪教徒发动起义与破坏，随后军团渗入目标世界，进一步制造混乱和恐慌，逐步摧毁敌人的关键战略资源与指挥能力。时机成熟，才实施“折磨”本身——从上百个方向同时发动压倒性的终结攻势，通常由精锐终结者与重装甲部队领衔。这一战法处于军团战略核心，叛乱时期享有崇高地位的“折磨大师”职衔便体现了这一点。它由阿尔法瑞斯麾下的军团在大远征期间创立，至今仍受各战帮推崇。')
p(182,'与大多数混沌星际战士军团不同，阿尔法军团很少在恐惧之眼内部活动，因此没有像其他叛徒战士那样经历亚空间的时间扭曲。荷鲁斯之乱已过去一万年，他们却依然活跃，令许多审判官争论不休。按审判官克莱文的说法，军团招募新兵、实施基因改造，并训练他们执行任务，整套过程都在帝国境内进行。')
p(189,'荷鲁斯之乱前，阿尔法军团便已在帝国不知情、未批准的情况下，秘密研发特殊武器与技术。他们在帝国境内外经营隐蔽军工厂与武器储藏点，也是首个制造专门穿透陶钢动力甲的爆矢弹的军团，因此在登陆点大屠杀初期占得先机。他们还取得少量 Mk VI 渡鸦型动力甲，通过逆向工程，仿制出“渡鸦-阿尔法”型。')
p(191,'阿尔法军团掌握变色龙式的伪装技术，能够改变外在形貌，不仅可冒充其他军团战士，甚至能伪装为未经强化的普通人类。')
p(195,'所有星际战士军团都会为新兵安排艰苦考验，但叛乱前的阿尔法军团以小队为单位考核：要么全队通过，要么全队失败；鲁莽逞英雄不受欢迎。整体计划高于一切，其价值超过任何一名战士。这体现了军团的核心理念：他们是一个整体，却能同时在多处出击。这份团结也表现在其他方面。军团决策相当公开，并具有一定民主性，任何军衔的人，包括非阿斯塔特特工，都可在筹划会议上自由发言。这种自由不限于军事事务：他们也会讨论哲学与银河政治，而同类讨论在其他帝国机构常被禁止或压制。后来，原体挑选新兵时，尤为看重智力与主动性。')
p(199,'军团中与常规连、营、战团相当的部队编制，有“折磨”“大队”“天军”和“仪器”等称呼。这些结构并不固定，而是按任务需要组建或拆分。军团层级的顶端，是获授“折磨大师”之衔的人；这一头衔用于指定某一战区阿尔法部队的总指挥。')
p(201,'阿尔法军团将自己视作真正的“群”：即便斩去“头颅”，整体也能继续运作。普通战士会冒用原体身份，迷惑外人；他们甚至认为，哪怕“真正的”阿尔法瑞斯被杀，也不会显著损害军团实力。面对军团外的人询问时，每名战士都会自报姓名为“阿尔法瑞斯”，即使在场的不止一人。')
p(203,'军团每到一个战区、参与一场战役，都会招募非阿斯塔特专家，通常选自帝国武装部队。这些特工常留在原职，随时听候阿尔法军团召唤。他们被称为“斯帕拉托伊”（Sparatoi），意为“播种之人”，指他们像种子一样被安插进其他组织。身份暴露的特工只要尚可保全，就不会被轻易舍弃；阿尔法战士会不惜代价保护他们，或掩藏其存在，甚至杀死其他帝国人员以灭口。特工身上都纹有小型九头蛇徽记。')
p(206,'荷鲁斯之乱后，外界对阿尔法军团内部结构的了解，比此前更加有限。曾有人成功刺杀被认为是高级军官的成员，却几乎看不出军团行动因此受损。其徽记九头蛇是一种多首神话生物，即便斩去一颗头仍能继续战斗。这既像是军团指挥结构的写照，也呼应了其多路出击的战术。')
p(210,'据信，叛乱后的阿尔法军团以独立秘密小组的形式，潜藏在帝国各处，协调混沌邪教徒活动，颠覆帝国统治。各组互不依赖，摧毁一组不会妨碍整体任务，但军团仍以松散方式协调银河范围内的行动。由谁协调、如何协调，对帝国而言大多仍是谜。许多人认为，关键在于那些“特工”：他们看起来是普通人类，却接受过有限的心理催眠处理，对军团绝对忠诚。他们深度融入帝国社会，联系阿尔法秘密小组与邪教徒，也是军团实现跨银河通信的主要途径。')
p(212,'阿尔法军团长于谋略与欺骗，为免引人注目，很少长期大规模集结。虽在叛乱后分化为无数战帮，他们仍保有许多其他叛徒军团所缺乏的共同目标。若有足够宏大的计划，或极具诱惑的机会，多支秘密小组与战帮便可能暂时联合，服从一名折磨大师的指挥，集结数百甚至数千名战士。')
p(214,'阿尔法瑞斯重视计划与协调，处理任何问题都会寻求替代方案与多重解法，让不同部队共同实现最终目标。这些理念被整个军团接受，叛乱后似乎仍在延续，尤其适合如今分散、隐秘的行动方式，成效显著。因此，军团中的混沌领主若展现出高超的欺敌本领，便可能获称“佯动大师”。')
p(218,'M42，折磨大师所罗门·阿库拉组建了规模可观的战帮联盟“幽灵军团”，意图对帝国统治构成实质威胁。联盟除他自己的巨蛇之牙外，还包括自由之枪、蔽影之手、忏悔之子、无面者、毒液之子、首击与锈血者。')
p(223,'阿尔法军团与太空野狼、火蜥蜴并列，属于最初的“三叶草”军团，拥有特点鲜明、单独培育的基因种子，其资料由帝皇亲自列为高度机密。具体特殊之处尚不清楚，只知这是统一战争末期，为阿斯塔特军团创造的最后一个基因种子品系。')
p(225,'阿尔法军团最显著的异常之一，是成员外貌近乎一致。大远征期间，大多数，甚至可能所有军团战士，都肤色白皙、剃着光头，面容近似原体阿尔法瑞斯。')
p(227,'大远征时期，有些阿尔法战士即使以阿斯塔特标准衡量也格外高大，这有利于阿尔法瑞斯混淆视听。原体下令，所有军团战士都应尽量容貌一致，而他们模仿的蓝本，正是阿尔法瑞斯与欧米伽。')
p(229,'由于主要在恐惧之眼以外活动，阿尔法军团的基因种子如今被认为大体未遭亚空间污染。不过，部分成员仍有可见变异与肢体扭曲。究竟源自最初的缺陷，还是在延续万年的“万古长战”中形成，尚不得而知。')
n.update({'A0561-B0174':'末句被召唤的是恶魔，不是被招募的教派本身。','A0561-B0178':'cell members 为秘密小组成员，不是军衔较低的基层成员。','A0561-B0182':'all within Imperial territory 修饰招募、改造和训练全过程，原译将地点仅接到任务范围上。','A0561-B0191':'unaugmented 是未经强化改造，原译未经审计属于明显词义错误。','A0561-B0199':'三种常规军制与四个阿尔法称呼在源文中未逐一对应，译文不强配；Instruments 暂沿仪器，明确为部队代号。Harrowmaster统一折磨大师。','A0561-B0203':'Sparatoi 原文释义是播种之人，与原译持剑者不符；暂保留音译斯帕拉托伊并附释义。compromised 指身份或安全遭破坏，按特工语境译暴露。','A0561-B0214':'Diversion 在战术语境为牵制、佯动，原译转移大师过于字面，暂译佯动大师。','A0561-B0218':'M42战帮联盟与早期秘密军团同名 Ghost Legion，但为不同时期的组织形态，不能视为组织史从未改变。','A0561-B0225':'bald head 描述无发外观，不单独推断病理脱发；按军团一致造型作光头。'})
